const tabId = 918806508;

// Let's test a batch of official URLs
const testUrls = [
  // O'Neill MPA & MSES
  "https://oneill.indiana.edu/masters/degrees-certificates/master-public-affairs/index.html",
  "https://oneill.indiana.edu/masters/degrees-certificates/master-science-environmental-science/index.html",
  "https://oneill.indiana.edu/masters/admissions/index.html",
  "https://oneill.indiana.edu/masters/cost-financial-aid/index.html",
  // Luddy Bloomington MS CS & MS HCID & MS Data Science
  "https://luddy.indiana.edu/academics/degrees/computer-science/ms/index.html",
  "https://luddy.indiana.edu/academics/degrees/human-computer-interaction-design/ms/index.html",
  "https://luddy.indiana.edu/academics/degrees/data-science/ms/index.html",
  // Kelley MSIS & MBA
  "https://kelley.iu.edu/programs/ms-information-systems/index.html",
  "https://kelley.iu.edu/programs/full-time-mba/index.html",
  // College of Arts & Sciences
  "https://psych.indiana.edu/graduate/index.html",
  "https://english.indiana.edu/graduate/mfa-creative-writing/index.html",
  // School of Education HESA
  "https://education.indiana.edu/programs/masters/higher-education-student-affairs/index.html",
  // Indianapolis: Lilly Family School of Philanthropy MA
  "https://philanthropy.indianapolis.iu.edu/academics/masters/index.html",
  // Indianapolis: Luddy MS HCI
  "https://luddy.indianapolis.iu.edu/degrees-programs/graduate/human-computer-interaction-ms/index.html",
  // Indianapolis: Fairbanks MHA
  "https://fsph.indianapolis.iu.edu/academics/masters/mha/index.html"
];

const results = [];
for (const url of testUrls) {
  try {
    await tool.navigate({ tabId, url });
    await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 5000 });
    const res = await browserjs(tabId, () => ({
      title: document.title,
      url: window.location.href,
      h1: document.querySelector('h1')?.textContent?.trim()
    }));
    results.push({ testUrl: url, ok: true, ...res });
  } catch (e) {
    results.push({ testUrl: url, ok: false, error: e.toString() });
  }
}

console.log(JSON.stringify(results, null, 2));

