const tabId = 918806508;

const degreesQuery = await browserjs(tabId, async () => {
  // Query degrees from bloomington and indianapolis
  async function getDegrees(campus, type, limit=50) {
    const res = await fetch(`https://exdd-academics.webapps.iu.edu/api/public/v1/endpoint/degrees?campus=${campus}&program_type=${type}&perPage=${limit}`);
    const json = await res.json();
    return json.data || [];
  }

  const blMasters = await getDegrees('bloomington', '7', 100);
  const indyMasters = await getDegrees('indianapolis', '7', 100);

  return {
    blCount: blMasters.length,
    indyCount: indyMasters.length,
    blSchools: [...new Set(blMasters.flatMap(d => d.schools.map(s => s.name)))],
    indySchools: [...new Set(indyMasters.flatMap(d => d.schools.map(s => s.name)))],
    blSample: blMasters.map(d => ({ name: d.name, degree: d.degree, school: d.schools[0]?.name, url: d.url })),
    indySample: indyMasters.map(d => ({ name: d.name, degree: d.degree, school: d.schools[0]?.name, url: d.url }))
  };
});

console.log("BL Schools:", degreesQuery.blSchools);
console.log("Indy Schools:", degreesQuery.indySchools);

