const tabId = 918806508;
const mpaDeadlines = await browserjs(tabId, () => {
  const pSelect = document.getElementById('apply-select-program');
  const tSelect = document.getElementById('apply-select-type');

  function getDetailsFor(prog, type) {
    pSelect.value = prog;
    pSelect.dispatchEvent(new Event('change', { bubbles: true }));
    tSelect.value = type;
    tSelect.dispatchEvent(new Event('change', { bubbles: true }));

    // Find output container
    const container = document.querySelector('#apply-output') || document.querySelector('.apply-output') || document.querySelector('[data-apply-output]') || document.querySelector('.results') || document.querySelector('#program-details');
    return {
      prog,
      type,
      containerText: container ? container.innerText : null,
      allText: document.querySelector('main')?.innerText
    };
  }

  const dom = getDetailsFor('Master of Public Affairs (MPA)', 'Domestic');
  const intl = getDetailsFor('Master of Public Affairs (MPA)', 'International');
  const msesDom = getDetailsFor('MS in Environmental Science (MSES)', 'Domestic');
  return { dom, intl, msesDom };
});

console.log("DOM text preview:", mpaDeadlines.dom.allText.slice(1000, 2500));

