const tabId = 918806508;

// First, let's look up the URLs for these 4 programs using our degrees endpoint or direct navigation
const queryRes = await browserjs(tabId, async () => {
  const progs = [
    'philanthropic',
    'human-computer',
    'health administration',
    'forensic'
  ];
  const results = {};
  for (const p of progs) {
    const res = await fetch(`https://exdd-academics.webapps.iu.edu/api/public/v1/endpoint/degrees?campus=indianapolis&program_type=7&q=${encodeURIComponent(p)}`);
    const json = await res.json();
    results[p] = json.data?.map(d => ({ name: d.name, degree: d.degree, school: d.schools[0]?.name, url: d.url }));
  }
  return results;
});

console.log(JSON.stringify(queryRes, null, 2));

