const tabId = 918806508;
// Let's check funding on the Forensic Science program or School of Science graduate funding
const fisAid = await browserjs(tabId, async () => {
  try {
    const res = await fetch("https://science.indianapolis.iu.edu/admissions/graduate/funding.html");
    if (res.ok) {
      const html = await res.text();
      return { ok: true, snippet: html.slice(0, 1000) };
    }
  } catch (e) {}

  // Look for any links on current page related to funding or tuition
  const links = Array.from(document.querySelectorAll('a')).map(a => ({ text: a.textContent.trim(), href: a.href }));
  return {
    fundingLinks: links.filter(l => l.text.toLowerCase().includes('aid') || l.text.toLowerCase().includes('cost') || l.text.toLowerCase().includes('tuition') || l.text.toLowerCase().includes('funding'))
  };
});
console.log(JSON.stringify(fisAid, null, 2));

