// We have tab 918806481 (CAS) and tab 918806508.
// Let's set tab 918806508 to Option 1: O'Neill MPA program page
const tab1 = 918806508;
await tool.navigate({ tabId: tab1, url: "https://oneill.indiana.edu/masters/degrees-certificates/public-affairs/index.html" });

// Let's create tabs for Options 2, 3, 4, 5, 6, plus O'Neill apply page:
const tabOnaApply = (await tool.tabs_create({ url: "https://oneill.indiana.edu/masters/apply/index.html?apply-select-program=Master+of+Public+Affairs+%28MPA%29&apply-select-type=Domestic#drop" })).details.tabId;

// Option 2: Luddy MS HCID
const tabHcid = (await tool.tabs_create({ url: "https://luddy.iu.edu/academics/masters/hcid.html" })).details.tabId;

// Option 3: Kelley MSIS
const tabMsis = (await tool.tabs_create({ url: "https://kelley.iu.edu/programs/ms-information-systems/index.html" })).details.tabId;

// Option 4: Luddy MS CS
const tabCs = (await tool.tabs_create({ url: "https://luddy.iu.edu/academics/masters/computer-science.html" })).details.tabId;

// Option 5: Lilly Family School MA in Philanthropic Studies
const tabLilly = (await tool.tabs_create({ url: "https://philanthropy.indianapolis.iu.edu/academics/degrees/ma/index.html" })).details.tabId;

// Option 6: Fairbanks MHA
const tabMha = (await tool.tabs_create({ url: "https://fairbanks.indianapolis.iu.edu/academics/masters/mha/index.html" })).details.tabId;

console.log("Created tabs:", {
  tab1_oneill_mpa: tab1,
  tab_oneill_apply: tabOnaApply,
  tab_hcid: tabHcid,
  tab_msis: tabMsis,
  tab_cs: tabCs,
  tab_lilly: tabLilly,
  tab_mha: tabMha
});

