// Let's gather specific curriculum details and faculty highlights for the 6 options

// 1. O'Neill MPA Curriculum & Concentrations
const mpaCurric = await browserjs(918806508, () => {
  const links = Array.from(document.querySelectorAll('a')).map(a => ({ text: a.textContent.trim(), href: a.href }));
  return {
    concentrations: links.filter(l => l.href.includes('concentrations')).map(l => l.text),
    curricLinks: links.filter(l => l.href.includes('curriculum') || l.href.includes('capstone'))
  };
});

// 2. Luddy HCID Curriculum & Studio details
const hcidCurric = await browserjs(918806510, () => {
  const text = document.querySelector('main')?.innerText || document.body.innerText;
  return {
    length: text.length,
    snippet: text.slice(text.indexOf('Curriculum'), text.indexOf('Curriculum') + 1500)
  };
});

// 3. Kelley MSIS Curriculum & Placement
const msisCurric = await browserjs(918806511, () => {
  const text = document.querySelector('main')?.innerText || document.body.innerText;
  return {
    salary: text.match(/\$[\d,]+/g),
    snippet: text.slice(0, 1500)
  };
});

// 4. Luddy CS details
const csDetails = await browserjs(918806512, () => {
  const text = document.querySelector('main')?.innerText || document.body.innerText;
  return {
    salary: text.match(/\$[\d,]+/g),
    snippet: text.slice(text.indexOf('Curriculum'), text.indexOf('Curriculum') + 1200)
  };
});

// 5. Lilly Family School MA details
const lillyDetails = await browserjs(918806513, () => {
  const text = document.querySelector('main')?.innerText || document.body.innerText;
  return {
    snippet: text.slice(0, 1500)
  };
});

// 6. Fairbanks MHA details
const mhaDetails = await browserjs(918806514, () => {
  const text = document.querySelector('main')?.innerText || document.body.innerText;
  return {
    snippet: text.slice(0, 1500)
  };
});

console.log("MPA details:", JSON.stringify(mpaCurric, null, 2));
console.log("HCID snippet:", hcidCurric.snippet);
console.log("MSIS snippet:", msisCurric.snippet.slice(0, 500));
console.log("CS snippet:", csDetails.snippet);

